const USE_SVG = false, SCL = 4;
let PENS, BG, S, svgGr;

function setup() {
	if (USE_SVG) {
		createCanvas(SCL * 297, SCL * 210);
	} else {
		createCanvas(windowWidth, windowHeight);
	}
	describe("iso cube packing")
	S = max(width, height);
	PENS = [...random(palettes)];
	BG = adjColorSaturation(PENS.splice(0, 1)[0], 0.25);
	background(BG);
	loop();
}

function draw() {
	svgGr = [];
	for (let i = 0; i < PENS.length; i++) svgGr[i] = ``;

	const num = ~~random(1, 6);
	S /= num;
	let numY = num;
	let numX = ~~(width/S)

	for (j = 0; j < numY; j++) {
		for (i = 0; i < numX; i++) {
			const x = S/2 + i * S + (width-numX*S)/2;
			const y = S/2 + j * S + (height-numY*S)/2;
			const clrIdx = ~~random(PENS.length);
			drawShape(x, y, S * 0.925, 6, clrIdx);
		}		
	}

	// noLoop() removed for animation
}

function polar2cart(a, r, x, y) {
	x += cos(a) * r;
	y += sin(a) * r;
	return {x, y};
}

function drawShape(x, y, sze, num, clrIdx) {
	noFill();
	noStroke();
	const clr = PENS[clrIdx];
	if (USE_SVG) stroke(clr);

	let currOr = random() < 0.5, lastF;
	for (let i = num; i >= 0; i--) {
		const f = i/num;
		if (i > 0 && i < num && random() < 0.25) continue;
		// circle(x, y, sze * f);

		if (i > 0) {
			let svgStr = `<polyline points="`;
			beginShape();
			for (let j = 0; j <= 6; j++) {
				const a = j/6 * TAU;
				const p = polar2cart(a + PI/6, sze * f * 0.5, x, y);
				vertex(p.x, p.y)
				svgStr += `${nf(p.x, 0, 2)},${nf(p.y, 0, 2)} `;
			}
			endShape();
			svgStr += `" />\n`;
			svgGr[clrIdx%PENS.length] += svgStr;
		}

		if (lastF) {
			let pts = []; // vor faces
			for (let j = 0; j < 6; j++) {
				var a = j/6 * TAU;
				const p1 = polar2cart(a + PI/6 + (currOr ? 0 : PI/3), sze * lastF * 0.5, x, y);
				const p2 = polar2cart(a + PI/6 + (currOr ? 0 : PI/3), sze * f * 0.5, x, y);
				pts.push(p1, p2);
				if (j%2) continue;
				line(p1.x, p1.y, p2.x, p2.y);
				svgGr[clrIdx%PENS.length] += `<polyline points="${nf(p1.x, 0, 2)},${nf(p1.y, 0, 2)} ${nf(p2.x, 0, 2)},${nf(p2.y, 0, 2)} " />n`;
			}
			// faces, pts[] 0..11
			if (!USE_SVG) {
				drawFace([pts[4], pts[6], pts[8], pts[9], pts[7], pts[5]], adjColorBrightness(clr, currOr ? 0.5 : 1));
				drawFace([pts[0], pts[2], pts[4], pts[5], pts[3], pts[1]], adjColorBrightness(clr, currOr ? 1 : 1.5));
				drawFace([pts[8], pts[10], pts[0], pts[1], pts[11], pts[9]], adjColorBrightness(clr, currOr ? 1.5: 0.5));
			}
		}

		lastF = f;
		currOr = !currOr; // reverse inner/outer orientation
	}
}

function drawFace(pts, clr) {
	push();
	fill(clr);
	beginShape();
	for (const p of pts) vertex(p.x, p.y);
	endShape();
	pop();
}


